<?php
declare(strict_types=1);

function st_finance_form(string $action,string $environment,?int $eventId=null): void {
    echo csrf_field().'<input type="hidden" name="action" value="finance_'.e($action).'"><input type="hidden" name="environment" value="'.e($environment).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(24)).'">';
    $section=is_string($_GET['section']??null)&&in_array($_GET['section'],['finance','budgets','expenses','reports'],true)?$_GET['section']:'finance';
    echo '<input type="hidden" name="return_section" value="'.$section.'">';
    if($eventId===null&&in_array($action,['settlement_record','reconcile'],true)&&isset($_GET['event_id'])&&is_scalar($_GET['event_id'])&&(int)$_GET['event_id']>0)$eventId=(int)$_GET['event_id'];
    if($eventId!==null)echo '<input type="hidden" name="event_id" value="'.$eventId.'">';
}
function st_finance_export_link(string $report,string $environment,?int $eventId): string {return '/admin.php?section=reports&export='.rawurlencode($report).'&environment='.$environment.($eventId===null?'':'&event_id='.$eventId);}
function st_finance_value(int $amount): string {return number_format($amount/100,2,'.','');}
function st_finance_view(array $u,string $section,?int $studioEventId=null): void {
    st_finance_permission($u,'view');
    $environment='live';
    if($studioEventId!==null)st_finance_event($u,$studioEventId);
    $events=st_scoped_events($u);$global=st_event_ids($u)===null;$db=cms_db();$summary=st_finance_summary($u,$studioEventId,$environment);
    $tabs=['finance'=>'Finance overview','budgets'=>'Allocations','expenses'=>'Expenses','reports'=>'Reports & closeout'];
    $eventTitles=[];foreach($events as $event)$eventTitles[(int)$event['id']]=$event['title'];
    ?>
    <div class="finance-controls list-toolbar"><?php if(cms_can($u,'finance','export')): ?><a class="quiet-button" href="<?= e(st_finance_export_link('summary',$environment,$studioEventId)) ?>">Export summary</a><?php endif; ?></div>
    <?php if($environment==='test'): ?><div class="notice warning" role="status">Test accounting is separate from live receipts, budgets and spending. These figures do not represent real money.</div><?php endif; ?>
    <nav class="finance-tabs settings-jumps" aria-label="Finance sections"><?php foreach($tabs as $key=>$label): ?><a href="/admin.php?section=<?= $key ?>&environment=<?= $environment ?><?= $studioEventId===null?'':'&event_id='.$studioEventId ?>" <?= $section===$key?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
    <?php if($section==='finance'): ?>
        <div class="metric-grid stats-grid finance-metrics"><?php foreach(['net_registration'=>'Registration receipts','manual_income'=>'Other receipts','paid_expenses'=>'Recorded spending','approved_commitments'=>'Approved, unpaid','available_budget'=>'Budget remaining','net_position'=>'Net position after fees'] as $key=>$label): ?><article class="stat-card"><span><?= $label ?></span><strong><?= e(az_money($summary[$key])) ?></strong></article><?php endforeach; ?></div>
        <div class="finance-grid dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Registration accounts</h2><span class="badge">Event receipts</span></div><dl class="finance-breakdown"><div><dt>Confirmed registration payments</dt><dd><?= e(az_money($summary['gross'])) ?></dd></div><div><dt>Recorded refunds</dt><dd><?= e(az_money($summary['refunds'])) ?></dd></div><div><dt>People who paid</dt><dd><?= $summary['paying_participants'] ?></dd></div><div><dt>Valid tickets / checked in</dt><dd><?= $summary['valid_tickets'] ?> / <?= $summary['checkins'] ?></dd></div><div><dt>Awaiting screenshot or review</dt><dd><?= $summary['pending_orders'] ?> orders</dd></div><?php if($summary['unsettled_gross']): ?><div><dt>Historical receipts awaiting reconciliation</dt><dd><?= e(az_money($summary['unsettled_gross'])) ?></dd></div><?php endif; ?></dl><p class="help">Only approved payments count as registration income. Payment details belong to each event. Compare event credits with the receiving accounts in Reports; budgets and spending are tracked separately.</p><?php if($summary['post_settlement_refunds']): ?><div class="notice warning"><?= e(az_money($summary['post_settlement_refunds'])) ?> refunded after bank batches were recorded. Reconcile these adjustments against the next bank statement.</div><?php endif; ?></section>
        <section class="panel"><div class="panel-heading"><h2>Review queue</h2><span class="badge"><?= $summary['submitted_expenses'] ?> submitted</span></div><?php $queue=st_finance_expense_queue($u,$studioEventId,$environment);if(!$queue): ?><p class="empty-message">No expenses are waiting for approval or payment.</p><?php endif;foreach($queue as $expense): ?><a class="review-row" href="/admin.php?section=expenses&environment=<?= $environment ?>&event_id=<?= (int)$expense['event_id'] ?>&expense=<?= (int)$expense['id'] ?>#expense-<?= (int)$expense['id'] ?>"><span><?= e($expense['title']) ?><small><?= e($expense['event_title']) ?> · <?= e($expense['status']) ?></small></span><strong><?= e(az_money((int)$expense['amount'])) ?></strong></a><?php endforeach; ?></section></div>
        <section class="panel"><div class="panel-heading"><h2>Recent journal</h2><a class="text-button" href="/admin.php?section=reports&environment=<?= $environment ?><?= $studioEventId===null?'':'&event_id='.$studioEventId ?>">All financial records</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Financial register"><table><thead><tr><th>Date</th><th>Event</th><th>Record</th><th>Reference</th><th>Amount</th></tr></thead><tbody><?php $ledger=st_finance_rows($u,'ledger',$studioEventId,$environment,12);foreach($ledger as $entry): ?><tr><td><?= e(substr($entry['created_at'],0,10)) ?></td><td><?= e($entry['event_title']) ?></td><td><?= e($entry['title']) ?><small><?= e(str_replace('_',' ',strtolower($entry['kind']))) ?></small></td><td><?= e($entry['reference']) ?></td><td><?= e(az_money((int)$entry['amount'])) ?></td></tr><?php endforeach;if(!$ledger): ?><tr><td colspan="5" class="empty-message">Manual receipts and recorded expenses will appear here. Registration receipts remain in Payments.</td></tr><?php endif; ?></tbody></table></div></section>
        <?php if($global&&cms_can($u,'finance','record'))st_finance_income_form($u,$events,$studioEventId,$environment); ?>
    <?php elseif($section==='budgets'): ?>
        <div class="metric-grid stats-grid"><?php foreach(['allocated'=>'Allocated budget','paid_expenses'=>'Spent','approved_commitments'=>'Reserved for approvals','available_budget'=>'Available to approve'] as $key=>$label): ?><article class="stat-card"><span><?= $label ?></span><strong><?= e(az_money($summary[$key])) ?></strong></article><?php endforeach; ?></div>
        <p class="page-help">Approved expenses reserve their amount immediately. Payments move that reserve into recorded spending. Allocations cannot drop below committed and spent money.</p>
        <section class="panel"><div class="table-wrap" tabindex="0" role="region" aria-label="Financial register"><table><thead><tr><th>Event</th><th>Allocation</th><th>Committed + spent</th><th>Available</th><th>Period</th><th>Change allocation</th></tr></thead><tbody><?php foreach($events as $event):if($studioEventId!==null&&$studioEventId!==(int)$event['id'])continue;$budget=st_finance_budget($db,(int)$event['id'],$environment);$reserved=st_finance_reserved($db,(int)$event['id'],$environment); ?><tr><td><strong><?= e($event['title']) ?></strong></td><td><?= e(az_money((int)$budget['allocated'])) ?></td><td><?= e(az_money($reserved)) ?></td><td><?= e(az_money((int)$budget['allocated']-$reserved)) ?></td><td><span class="badge"><?= $budget['closed']?'Closed':'Open' ?></span></td><td><?php if($global&&cms_can($u,'finance','allocate')&&!$budget['closed']): ?><form method="post" class="finance-allocation-form"><?php st_finance_form('allocate',$environment,(int)$event['id']); ?><input type="hidden" name="revision" value="<?= (int)$budget['revision'] ?>"><label class="sr-only" for="allocation-<?= (int)$event['id'] ?>">Rupee allocation for <?= e($event['title']) ?></label><input id="allocation-<?= (int)$event['id'] ?>" name="amount" type="number" min="0" step="0.01" value="<?= st_finance_value((int)$budget['allocated']) ?>" required><label class="sr-only" for="allocation-note-<?= (int)$event['id'] ?>">Reason for allocation change</label><input id="allocation-note-<?= (int)$event['id'] ?>" name="note" placeholder="Reason / approval reference" maxlength="500" required><button class="quiet-button" type="submit">Save</button></form><?php else: ?>Finance controlled<?php endif; ?></td></tr><?php endforeach;if(!$events): ?><tr><td colspan="6" class="empty-message">No event access is assigned to your account.</td></tr><?php endif; ?></tbody></table></div></section>
    <?php elseif($section==='expenses'): ?>
        <p class="page-help">Draft → Submit → Independent review → Record actual payment. Paid records stay immutable; returned money creates a linked reversal.</p>
        <?php $expensePage=is_scalar($_GET['expense_page']??null)?max(1,min(1000000,(int)$_GET['expense_page'])):1;$expenses=st_finance_rows($u,'expenses',$studioEventId,$environment,51,($expensePage-1)*50);$hasNextExpenses=count($expenses)>50;$expenses=array_slice($expenses,0,50);$edit=null;$editId=isset($_GET['expense'])&&is_scalar($_GET['expense'])?(int)$_GET['expense']:0;
        if($editId>0){$focusedExpense=st_finance_expense_record($u,$editId,$studioEventId,$environment);if($focusedExpense){if((int)$focusedExpense['created_by']===(int)$u['id']&&in_array($focusedExpense['status'],['DRAFT','REJECTED'],true))$edit=$focusedExpense;if(!in_array($editId,array_map(fn($r)=>(int)$r['id'],$expenses),true))array_unshift($expenses,$focusedExpense);}}
        if(cms_can($u,'finance','submit')&&$events)st_finance_expense_form($u,$events,$edit,$studioEventId,$environment); ?>
        <div class="submission-list finance-expenses"><?php if(!$expenses): ?><section class="panel empty-message">No expenses yet. Create a draft for your event to start its approval trail.</section><?php endif;foreach($expenses as $expense):$own=(int)$expense['created_by']===(int)$u['id'];$closed=(bool)st_finance_budget($db,(int)$expense['event_id'],$environment)['closed']; ?>
            <details class="panel submission finance-expense" id="expense-<?= (int)$expense['id'] ?>" <?= in_array($expense['status'],['SUBMITTED','APPROVED'],true)?'open':'' ?>><summary><span><strong><?= e($expense['title']) ?></strong><small>#<?= (int)$expense['id'] ?> · <?= e($expense['event_title']) ?> · <?= e(ucfirst($expense['category'])) ?></small></span><strong><?= e(az_money((int)$expense['amount'])) ?></strong><span class="badge <?= e(strtolower($expense['status'])) ?>"><?= e($expense['status']) ?></span></summary><div class="expense-detail"><dl><dt>Payee</dt><dd><?= e($expense['payee']) ?></dd><dt>Purpose</dt><dd><?= e($expense['description']) ?></dd><dt>Invoice reference</dt><dd><?= e($expense['invoice_reference']) ?></dd><dt>Maker / reviewer</dt><dd>Staff #<?= (int)$expense['created_by'] ?> / <?= $expense['reviewed_by']?'Staff #'.(int)$expense['reviewed_by']:'Awaiting review' ?></dd><?php if($expense['review_note']): ?><dt>Review note</dt><dd><?= e($expense['review_note']) ?></dd><?php endif;if($expense['payment_reference']): ?><dt>Payment reference</dt><dd><?= e($expense['payment_reference']) ?></dd><?php endif;if($expense['proof_evidence_id']): ?><dt>Receipt evidence</dt><dd><a class="text-button" href="/admin.php?finance_receipt=<?= (int)$expense['proof_evidence_id'] ?>">Download private receipt #<?= (int)$expense['proof_evidence_id'] ?></a></dd><?php endif; ?></dl></div>
            <?php if(!$closed): ?><div class="finance-expense-actions"><?php if($own&&cms_can($u,'finance','submit')&&in_array($expense['status'],['DRAFT','REJECTED'],true)): ?><a class="quiet-button" href="/admin.php?section=expenses&environment=<?= $environment ?>&event_id=<?= (int)$expense['event_id'] ?>&expense=<?= (int)$expense['id'] ?>#expense-editor">Edit draft</a><?php endif;if($own&&cms_can($u,'finance','submit')&&$expense['status']==='DRAFT'): ?><form method="post"><?php st_finance_form('expense_submit',$environment,(int)$expense['event_id']); ?><input type="hidden" name="id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$expense['revision'] ?>"><button class="primary-button" type="submit">Submit for approval</button></form><?php endif;
            if(!$own&&cms_can($u,'finance','approve')&&$expense['status']==='SUBMITTED'): ?><form method="post" class="inline-form"><?php st_finance_form('expense_approve',$environment,(int)$expense['event_id']); ?><input type="hidden" name="id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$expense['revision'] ?>"><label class="sr-only" for="review-<?= (int)$expense['id'] ?>">Review note for <?= e($expense['title']) ?></label><input id="review-<?= (int)$expense['id'] ?>" name="note" placeholder="Review note" required maxlength="500"><button class="primary-button" type="submit">Approve & reserve</button><button class="danger-button" name="action" value="finance_expense_reject" type="submit">Reject</button></form><?php endif;
            if($global&&!$own&&cms_can($u,'finance','record')&&$expense['status']==='APPROVED'): ?><form method="post" class="inline-form" data-confirm="Confirm this money has actually been paid. This records a payment and does not send money."><?php st_finance_form('expense_pay',$environment,(int)$expense['event_id']); ?><input type="hidden" name="id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$expense['revision'] ?>"><label class="sr-only" for="payment-ref-<?= (int)$expense['id'] ?>">Bank payment reference</label><input id="payment-ref-<?= (int)$expense['id'] ?>" name="payment_reference" placeholder="Actual bank payment reference" required maxlength="150"><button class="primary-button" type="submit">Record as paid</button></form><?php endif;
            if(($own&&cms_can($u,'finance','submit')&&in_array($expense['status'],['DRAFT','REJECTED','SUBMITTED'],true))||(!$own&&cms_can($u,'finance','approve')&&$expense['status']==='APPROVED')): ?><form method="post" class="inline-form"><?php st_finance_form('expense_void',$environment,(int)$expense['event_id']); ?><input type="hidden" name="id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$expense['revision'] ?>"><label class="sr-only" for="void-<?= (int)$expense['id'] ?>">Reason to withdraw expense</label><input id="void-<?= (int)$expense['id'] ?>" name="note" placeholder="Reason to withdraw" required maxlength="500"><button class="quiet-button" type="submit"><?= $expense['status']==='APPROVED'?'Release commitment':'Withdraw' ?></button></form><?php endif;
            if($global&&cms_can($u,'finance','record')&&$expense['status']==='PAID'): ?><details><summary>Record returned money</summary><form method="post" class="inline-form" data-confirm="Confirm the full expense amount has actually been returned. The original payment will be retained."><?php st_finance_form('expense_reverse',$environment,(int)$expense['event_id']); ?><input type="hidden" name="id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$expense['revision'] ?>"><label class="sr-only" for="return-ref-<?= (int)$expense['id'] ?>">Return transaction reference</label><input id="return-ref-<?= (int)$expense['id'] ?>" name="payment_reference" placeholder="Return transaction reference" required maxlength="150"><label class="sr-only" for="return-note-<?= (int)$expense['id'] ?>">Reason money was returned</label><input id="return-note-<?= (int)$expense['id'] ?>" name="note" placeholder="Reason" required maxlength="500"><button class="danger-button" type="submit">Record full reversal</button></form></details><?php endif; ?></div><?php endif; ?></details>
        <?php endforeach; ?></div><nav class="finance-pagination list-toolbar" aria-label="Expense pages"><span>Page <?= $expensePage ?></span><div class="row-actions"><?php if($expensePage>1): ?><a class="quiet-button" href="/admin.php?section=expenses&environment=<?= $environment ?>&event_id=<?= $studioEventId??0 ?>&expense_page=<?= $expensePage-1 ?>">Previous expenses</a><?php endif;if($hasNextExpenses): ?><a class="quiet-button" href="/admin.php?section=expenses&environment=<?= $environment ?>&event_id=<?= $studioEventId??0 ?>&expense_page=<?= $expensePage+1 ?>">Next expenses</a><?php endif; ?></div></nav>
        <?php if(cms_can($u,'finance','submit')&&$events): ?><details class="panel receipt-upload"><summary><strong>Private receipt library</strong><span>Upload supporting invoices</span></summary><p class="help">Receipts are private downloads for staff with this event's finance access. PDF, JPG, PNG or WebP up to 12 MB.</p><form method="post" enctype="multipart/form-data" class="form-grid"><?php st_finance_form('receipt_upload',$environment); ?><label class="field" for="receipt-event"><span>Event</span><select name="event_id" id="receipt-event" required><?php foreach($events as $event): ?><option value="<?= (int)$event['id'] ?>" <?= $studioEventId===(int)$event['id']?'selected':'' ?>><?= e($event['title']) ?></option><?php endforeach; ?></select></label><label class="field" for="receipt-file"><span>Invoice or receipt</span><input id="receipt-file" name="receipt" type="file" required accept="application/pdf,image/jpeg,image/png,image/webp"></label><div class="form-actions"><button class="primary-button" type="submit">Upload privately</button></div></form><?php $evidence=st_finance_rows($u,'evidence',$studioEventId,$environment,100);foreach($evidence as $receipt): ?><a class="review-row" href="/admin.php?finance_receipt=<?= (int)$receipt['id'] ?>"><span>#<?= (int)$receipt['id'] ?> · <?= e($receipt['title']) ?><small><?= e($receipt['event_title']) ?></small></span><span>Download</span></a><?php endforeach; ?></details><?php endif; ?>
    <?php elseif($section==='reports'): ?>
        <section class="panel"><h2>Accounting exports</h2><p class="help">CSV money values are integer paise for exact calculations. Every download is audited. Event archives include payment/refund snapshots, expenses, journal entries, receipt hashes and the complete financial activity trail.</p><div class="row-actions finance-export-actions"><?php if(cms_can($u,'finance','export')):foreach(['summary'=>'Summary CSV','budgets'=>'Allocation CSV','expenses'=>'Expense CSV','ledger'=>'Journal CSV','audit'=>'Financial activity CSV','closeouts'=>'Closeouts CSV'] as $key=>$label): ?><a class="quiet-button" href="<?= e(st_finance_export_link($key,$environment,$studioEventId)) ?>"><?= $label ?></a><?php endforeach;if($studioEventId!==null): ?><a class="primary-button" href="<?= e(st_finance_export_link('archive',$environment,$studioEventId)) ?>">Complete event archive</a><?php endif;else: ?><p class="empty-message">Your account does not have financial export access.</p><?php endif; ?></div></section>
        <?php az_event_receipts_view($u,$events,$studioEventId); ?>
        <section class="panel"><div class="panel-heading"><h2>Event closeout</h2><span class="badge">Permanent snapshots</span></div><p class="help">Resolve payment reviews, ticket availability, expense drafts and unpaid approvals before closing. Closing freezes new registrations, manual payment reviews and organiser finance changes. A retained snapshot includes registration answers, receiving accounts, payment reviews and ticket statuses. Reopen with a reason to make corrections.</p><?php if($global&&cms_can($u,'finance','close')): ?><div class="finance-close-grid"><?php foreach($events as $event):if($studioEventId!==null&&$studioEventId!==(int)$event['id'])continue;$budget=st_finance_budget($db,(int)$event['id'],$environment); ?><form method="post" class="finance-close-form" data-confirm="<?= $budget['closed']?'Reopen this accounting period? Existing closeout snapshots will remain.':'Close this event accounting period? All drafts and unpaid approvals must be resolved.' ?>"><?php st_finance_form($budget['closed']?'reopen':'close',$environment,(int)$event['id']); ?><strong><?= e($event['title']) ?></strong><span class="badge"><?= $budget['closed']?'Closed':'Open' ?></span><label class="sr-only" for="close-note-<?= (int)$event['id'] ?>">Closeout or reopening reason for <?= e($event['title']) ?></label><input id="close-note-<?= (int)$event['id'] ?>" name="note" placeholder="Approval reference / reason" required maxlength="1000"><button class="quiet-button" type="submit"><?= $budget['closed']?'Reopen with reason':'Close & snapshot' ?></button></form><?php endforeach; ?></div><?php endif; ?>
        <?php $closeouts=st_finance_rows($u,'closeouts',$studioEventId,$environment,100);foreach($closeouts as $closeout):$changed=st_finance_closeout_changed($u,$closeout); ?><article class="review-row"><span><strong><?= e($closeout['event_title']) ?></strong><small><?= e($closeout['created_at']) ?> · <?= e($closeout['note']) ?></small><code><?= e(substr($closeout['snapshot_hash'],0,20)) ?>…</code></span><span class="badge <?= $changed?'warning':'approved' ?>"><?= $changed?'Changed since closeout':'Snapshot matches' ?></span></article><?php endforeach;if(!$closeouts): ?><p class="empty-message">No accounting periods have been closed yet.</p><?php endif; ?></section>
        <?php if($global&&cms_can($u,'finance','record')): ?><section class="panel"><h2>Manual receipt corrections</h2><p class="help">Reverse only when a receipt was actually returned or a mistaken entry needs correction. Original entries remain in the journal.</p><?php $entries=st_finance_rows($u,'ledger',$studioEventId,$environment,100);$reversed=array_column(array_filter($entries,fn($r)=>$r['reverses_id']!==null),'reverses_id');foreach($entries as $entry):if($entry['kind']!=='MANUAL_INCOME'||in_array($entry['id'],$reversed))continue; ?><details><summary><?= e($entry['title']) ?> · <?= e(az_money((int)$entry['amount'])) ?> · <?= e($entry['reference']) ?></summary><form method="post" class="inline-form"><?php st_finance_form('income_reverse',$environment,(int)$entry['event_id']); ?><input type="hidden" name="id" value="<?= (int)$entry['id'] ?>"><label class="sr-only" for="income-return-ref-<?= (int)$entry['id'] ?>">Return or correction reference</label><input id="income-return-ref-<?= (int)$entry['id'] ?>" name="reference" placeholder="Return / correction reference" required maxlength="150"><label class="sr-only" for="income-return-note-<?= (int)$entry['id'] ?>">Correction reason</label><input id="income-return-note-<?= (int)$entry['id'] ?>" name="note" placeholder="Reason" required maxlength="500"><button class="danger-button" type="submit">Record reversal</button></form></details><?php endforeach; ?></section><?php endif; ?>
    <?php endif;
}
function st_finance_income_form(array $u,array $events,?int $eventId,string $environment): void { ?>
    <details class="panel"><summary><strong>Record sponsorship or other income</strong><span>Sponsorships, grants and donations</span></summary><p class="help">Record only money received. Approved registration payments are counted automatically; do not enter them again here. Store a receipt reference; avoid recording bank account numbers or payment credentials.</p><form method="post" class="form-grid"><?php st_finance_form('income_post',$environment); ?><label class="field" for="income-event"><span>Event allocation</span><select id="income-event" name="event_id" required><?php foreach($events as $event): ?><option value="<?= (int)$event['id'] ?>" <?= $eventId===(int)$event['id']?'selected':'' ?>><?= e($event['title']) ?></option><?php endforeach; ?></select></label><label class="field" for="income-source"><span>Source</span><select id="income-source" name="source"><option value="sponsorship">Sponsorship</option><option value="grant">Grant</option><option value="donation">Donation</option><option value="other">Other receipt</option></select></label><label class="field" for="income-title"><span>Receipt description</span><input id="income-title" name="title" required maxlength="180"></label><label class="field" for="income-amount"><span>Received amount (₹)</span><input id="income-amount" name="amount" type="number" min="0.01" step="0.01" required></label><label class="field" for="income-reference"><span>Unique receipt / bank reference</span><input id="income-reference" name="reference" required maxlength="150"></label><label class="field" for="income-note"><span>Evidence / allocation note</span><input id="income-note" name="note" required maxlength="500"></label><div class="form-actions"><button type="submit" class="primary-button">Record received income</button></div></form></details>
<?php }
function st_finance_expense_form(array $u,array $events,?array $edit,?int $eventId,string $environment): void {
    $selected=$edit?(int)$edit['event_id']:$eventId;$receipts=st_finance_rows($u,'evidence',$selected,$environment,100); ?>
    <details class="panel" id="expense-editor" <?= $edit?'open':'' ?>><summary><strong><?= $edit?'Edit draft #'.(int)$edit['id']:'Create an expense draft' ?></strong><span>Saved before submission</span></summary><form method="post" class="form-grid"><?php st_finance_form('expense_save',$environment); ?><input type="hidden" name="id" value="<?= $edit['id']??'' ?>"><input type="hidden" name="revision" value="<?= $edit['revision']??'' ?>"><label class="field" for="expense-event"><span>Event</span><select id="expense-event" name="event_id" required><?php foreach($events as $event):if($edit&&(int)$event['id']!==(int)$edit['event_id'])continue; ?><option value="<?= (int)$event['id'] ?>" <?= $selected===(int)$event['id']?'selected':'' ?>><?= e($event['title']) ?></option><?php endforeach; ?></select></label><label class="field" for="expense-category"><span>Category</span><select id="expense-category" name="category"><?php foreach(['production','prizes','hospitality','travel','equipment','marketing','venue','other'] as $category): ?><option value="<?= $category ?>" <?= ($edit['category']??'production')===$category?'selected':'' ?>><?= ucfirst($category) ?></option><?php endforeach; ?></select></label><label class="field" for="expense-title"><span>Expense title</span><input id="expense-title" name="title" value="<?= e($edit['title']??'') ?>" required maxlength="180"></label><label class="field" for="expense-payee"><span>Vendor / payee name</span><input id="expense-payee" name="payee" value="<?= e($edit['payee']??'') ?>" required maxlength="150"></label><label class="field" for="expense-amount"><span>Requested amount (₹)</span><input id="expense-amount" name="amount" type="number" min="0.01" step="0.01" value="<?= $edit?st_finance_value((int)$edit['amount']):'' ?>" required></label><label class="field" for="expense-invoice"><span>Invoice / quotation reference</span><input id="expense-invoice" name="invoice_reference" value="<?= e($edit['invoice_reference']??'') ?>" required maxlength="150"></label><label class="field wide" for="expense-description"><span>Purpose and budget justification</span><textarea id="expense-description" name="description" required maxlength="2000" rows="3"><?= e($edit['description']??'') ?></textarea></label><label class="field wide" for="expense-receipt"><span>Private receipt (optional)</span><select id="expense-receipt" name="proof_evidence_id"><option value="">Add later / use invoice reference</option><?php foreach($receipts as $receipt):if((int)$receipt['uploaded_by']!==(int)$u['id']&&st_event_ids($u)!==null)continue; ?><option value="<?= (int)$receipt['id'] ?>" <?= (int)($edit['proof_evidence_id']??0)===(int)$receipt['id']?'selected':'' ?>>#<?= (int)$receipt['id'] ?> · <?= e($receipt['event_title'].' · '.$receipt['title']) ?></option><?php endforeach; ?></select><small>Upload a receipt in the private library below. A receipt must belong to the same event and environment.</small></label><div class="form-actions"><button class="primary-button" type="submit">Save draft</button></div></form></details>
<?php }
function st_finance_bank_view(array $u,string $environment): void {
    $settlements=st_finance_rows($u,'settlements',null,$environment,100);$reconciliations=st_finance_rows($u,'reconciliations',null,$environment,20); ?>
    <section class="panel"><div class="panel-heading"><h2>Common bank reconciliation</h2><?php if(cms_can($u,'finance','export')): ?><a class="text-button" href="<?= e(st_finance_export_link('settlements',$environment,null)) ?>">Settlement CSV</a><?php endif; ?></div><p class="help">Use the gateway settlement report and bank statement. Link each verified order once. Batch net must match captures minus actual refunds and recorded gateway fees. No funds move when a record is saved.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Financial register"><table><thead><tr><th>Bank date</th><th>Gateway / batch</th><th>Captures</th><th>Refunds</th><th>Fees</th><th>Bank net</th><th>Bank reference</th></tr></thead><tbody><?php foreach($settlements as $batch): ?><tr><td><?= e($batch['bank_date']) ?></td><td><?= e(ucfirst($batch['provider']).' · '.$batch['reference']) ?></td><td><?= e(az_money((int)$batch['gross'])) ?></td><td><?= e(az_money((int)$batch['refunds'])) ?></td><td><?= e(az_money((int)$batch['fees'])) ?></td><td><?= e(az_money((int)$batch['net'])) ?></td><td><?= e($batch['bank_reference']) ?></td></tr><?php endforeach;if(!$settlements): ?><tr><td colspan="7" class="empty-message">No bank batches recorded yet. A paid order becomes a bank settlement only after verification against a deposit.</td></tr><?php endif; ?></tbody></table></div>
    <?php if(cms_can($u,'finance','record')): ?><details><summary>Record a verified bank batch</summary><form method="post" class="form-grid"><?php st_finance_form('settlement_record',$environment); ?><label class="field" for="settlement-provider"><span>Gateway</span><select id="settlement-provider" name="provider"><option value="phonepe">PhonePe</option><option value="razorpay">Razorpay (legacy)</option></select></label><label class="field" for="settlement-reference"><span>Gateway settlement reference</span><input id="settlement-reference" name="reference" required maxlength="150"></label><label class="field" for="settlement-date"><span>Bank deposit date</span><input id="settlement-date" name="bank_date" type="date" required></label><label class="field" for="settlement-bank-reference"><span>Bank statement deposit reference</span><input id="settlement-bank-reference" name="bank_reference" required maxlength="150"></label><label class="field wide" for="settlement-orders"><span>Captured order IDs in this batch</span><textarea id="settlement-orders" name="order_ids" required maxlength="5000" placeholder="12, 13, 14" rows="2"></textarea><small>Use internal numeric IDs from Payments. Up to 200 orders per batch.</small></label><label class="field" for="settlement-fees"><span>Gateway fees including tax (₹)</span><input id="settlement-fees" name="fees" type="number" step="0.01" min="0" required value="0.00"></label><label class="field" for="settlement-net"><span>Actual net bank deposit (₹)</span><input id="settlement-net" name="net" type="number" step="0.01" min="0" required></label><div class="form-actions"><button class="primary-button" type="submit">Record verified deposit</button></div></form></details>
    <details><summary>Compare the bank statement total</summary><p class="help">Enter the cumulative gateway deposits for this environment through the statement date. This comparison covers gateway deposits only, excluding manual sponsorship receipts and expense payments.</p><form method="post" class="form-grid"><?php st_finance_form('reconcile',$environment); ?><label class="field" for="reconcile-date"><span>Statement through date</span><input id="reconcile-date" name="statement_date" type="date" required></label><label class="field" for="reconcile-bank"><span>Cumulative gateway bank deposits (₹)</span><input id="reconcile-bank" name="bank_total" type="number" step="0.01" min="0" required></label><label class="field" for="reconcile-reference"><span>Statement reference</span><input id="reconcile-reference" name="reference" required maxlength="150"></label><label class="field" for="reconcile-note"><span>Reconciliation / difference explanation</span><input id="reconcile-note" name="note" required maxlength="1000"></label><div class="form-actions"><button class="primary-button" type="submit">Save reconciliation</button></div></form></details><?php endif; ?>
    <?php foreach($reconciliations as $reconciliation): ?><div class="review-row"><span><strong>Statement <?= e($reconciliation['statement_date']) ?></strong><small><?= e($reconciliation['reference'].' · '.$reconciliation['note']) ?></small></span><span class="badge <?= $reconciliation['difference']?'warning':'approved' ?>"><?= $reconciliation['difference']?'Difference '.e(az_money((int)$reconciliation['difference'])):'Matched '.e(az_money((int)$reconciliation['recorded_total'])) ?></span></div><?php endforeach; ?></section>
<?php }
